/**
 *
 * ScrollAreaHandle is the draggable handle within a scrollbar.
 *
 * [Live Demo](https://www.primereact.org/scrollarea/)
 *
 * @module ScrollAreaHandle
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { ScrollAreaRootInstance } from './ScrollAreaRoot.types';
/**
 * Defines passthrough(pt) options type in ScrollAreaHandle component.
 */
export type ScrollAreaHandlePassThroughType<E> = PassThroughType<ScrollAreaHandleInstance, E>;
/**
 * Defines passthrough(pt) options of ScrollAreaHandle component.
 */
export interface ScrollAreaHandlePassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: ScrollAreaHandlePassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in ScrollAreaHandle component.
 */
export interface ScrollAreaHandleProps extends BaseComponentProps<ScrollAreaHandleInstance, unknown, ScrollAreaHandlePassThrough> {
}
/**
 * Defines valid state in ScrollAreaHandle component.
 */
export interface ScrollAreaHandleState {
}
/**
 * Defines the methods and properties exposed by ScrollAreaHandle component.
 */
export interface ScrollAreaHandleExposes {
    /**
     * Instance of the ScrollArea component.
     */
    scrollarea: ScrollAreaRootInstance | undefined | null;
}
/**
 * Instance of ScrollAreaHandle component.
 */
export type ScrollAreaHandleInstance = ComponentInstance<ScrollAreaHandleProps, ScrollAreaHandleState, ScrollAreaHandleExposes>;
